(() => {
  const raw = (v) => String(v === undefined || v === null ? '' : v).trim().toLowerCase();
  const parse = (value) => {
    const v = raw(value);
    if (v === '' || v === 'none') return null;
    if (v.startsWith('#')) {
      const hex = v.length === 4 ? v.slice(1).split('').map((c) => c + c).join('') : v.slice(1);
      if (hex.length < 6) return null;
      return [0, 2, 4].map((i) => parseInt(hex.slice(i, i + 2), 16));
    }
    const cs = /^color\(srgb\s+([\d.]+)\s+([\d.]+)\s+([\d.]+)/.exec(v);
    if (cs !== null) return [1, 2, 3].map((i) => Math.round(Number(cs[i]) * 255));
    const m = /^rgba?\(([^)]+)\)/.exec(v);
    if (m === null) return null;
    return m[1].split(",").map((x) => Number.parseFloat(x)).slice(0, 3).map((x) => Math.round(x));
  };
  const alphaOf = (value) => {
    const m = /^rgba?\(([^)]+)\)$/.exec(raw(value));
    if (m === null) return 1;
    const parts = m[1].split(",").map((x) => x.trim());
    return parts.length === 4 ? Number.parseFloat(parts[3]) : 1;
  };
  const lin = (x) => {
    const v = x / 255;
    return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
  };
  const lum = (c) => 0.2126 * lin(c[0]) + 0.7152 * lin(c[1]) + 0.0722 * lin(c[2]);
  const ratio = (a, b) => {
    if (a === null || b === null) return 0;
    const x = lum(a);
    const y = lum(b);
    return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05);
  };
  const dist = (a, b) =>
    a === null || b === null ? 0 : Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
  const prop = (name) =>
    getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  const colour = (name) => parse(prop(name));
  const mix = (top, bottom, alpha) =>
    top.map((c, i) => Math.round(alpha * c + (1 - alpha) * bottom[i]));
  const bandRatio = (stripe, backdrop) => {
    const s = typeof stripe === "string" ? parse(stripe) : stripe;
    const b = typeof backdrop === "string" ? parse(backdrop) : backdrop;
    if (s === null || b === null) return 0;
    return ratio(mix(s, b, 0.7), b);
  };
  const styleOf = (el, name) => parse(getComputedStyle(el)[name]);
  window.__ac = { parse, alphaOf, ratio, dist, prop, colour, mix, bandRatio, styleOf };
  return Object.keys(window.__ac).length;
})()

(() => {
  const row = Array.from(document.querySelectorAll('.menu-item')).find((e) => (e.textContent || '').trim() === '{{text:userMenuSettings}}');
  if (row === undefined) throw new Error('settings menu item not found');
  row.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true }));
  row.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));
  return true;
})()

