steps.probe:
(() => {
  const select = Array.from(document.querySelectorAll('.settings-section select')).find((s) =>
    Array.from(s.options).some((option) => option.value === 'current'),
  );
  if (select === undefined) throw new Error('theme select not found');
  select.value = 'current';
  select.dispatchEvent(new Event('change', { bubbles: true }));
  return select.value;
})()

(() => {
  const radio = document.querySelector('input[name="settings-ui-mode"][value="light"]');
  if (radio === null) throw new Error('mode radio not found');
  radio.click();
  return radio.checked;
})()

(() => {
  const rows = Array.from(document.querySelectorAll('.dialog-backdrop .layer-color-row'));
  const row = rows.find((r) => {
    const scope = r.closest(".ui-field") || r.parentElement;
    const caption = scope === null ? null : scope.querySelector("label");
    return ((caption === null ? "" : caption.textContent) || "").trim() === '{{text:layersFocusStripe}}';
  });
  if (row === undefined) throw new Error('color row not found');
  const input = row.querySelector("input.ui-color-hex");
  if (input === null) throw new Error("hex input not found");
  input.value = '#ffffff';
  input.dispatchEvent(new Event('change', { bubbles: true }));
  return input.value;
})()

