(() => {
  const p = window.__ac;
  const stripe = p.prop('--layer-focus-stripe');
  const bg = p.prop('--layer-bg');
  const text = p.colour('--text');
  const themeBg = p.prop('--bg');
  return {
    stripe_present: stripe !== '',
    bg_present: bg !== '',
    band_contrast_ge_3: Number(p.bandRatio(stripe, bg).toFixed(2)) >= 3,
    band_contrast: Number(p.bandRatio(stripe, bg).toFixed(2)),
    bg_text_contrast_ge_4_5: Number(p.ratio(p.parse(bg), text).toFixed(2)) >= 4.5,
    bg_text_contrast: Number(p.ratio(p.parse(bg), text).toFixed(2)),
    stripe_not_white: p.dist(p.parse(stripe), [255, 255, 255]) > 6,
    bg_not_black: p.dist(p.parse(bg), [0, 0, 0]) > 6,
    stripe_on_theme_bg_ge_3: Number(p.bandRatio(stripe, themeBg).toFixed(2)) >= 3,
    stripe: stripe,
    bg: bg,
    theme_bg: themeBg,
  };
})()

